	@Test
	public void boundChecksReserveRenamedVariablesAcrossEveryUnionBranch() {
		ExclusiveStatement statement = selectedPhysicalAlias();
		statement.replaceChildNode(statement.getSubjectVar(), Var.of("__fedx_graph"));
		QueryBindingSet first = new QueryBindingSet();
		first.addBinding("object", Values.literal("first-object"));
		QueryBindingSet second = new QueryBindingSet();
		second.addBinding("object", Values.literal("second-object"));

		TupleExpr parsed = parse(QueryStringUtil.selectQueryStringBoundCheck(statement, List.of(first, second), null));

		assertThat(parsed.getBindingNames()).containsExactlyInAnyOrder("__fedx_graph_0", "__fedx_graph_1", "o_0",
				"o_1");
		assertThat(graphs(parsed)).hasSize(2).allSatisfy(selected -> {
			assertThat(selected.getGraphName().hasValue()).isFalse();
			assertThat(parsed.getBindingNames()).doesNotContain(selected.getGraphName().getName());
		});
	}

	private ExclusiveStatement selectedPhysicalAlias() {
		StatementPattern pattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("subject"), Var.of("predicate", Values.iri("urn:selected-alias-predicate"), true, true),
				Var.of("object"), Var.of("context", RDF4J.NIL, true, true));
		ExclusiveStatement statement = new ExclusiveStatement(pattern,
				new StatementSource("member", StatementSourceType.REMOTE), mock(QueryInfo.class));
		statement.setResolvedGraphSelection(new ResolvedGraphSelection(RDF4J.NIL, RDF4J.NIL, true));
		return statement;
	}

	private TupleExpr parse(String query) {
		return QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
	}

	private List<Graph> graphs(TupleExpr expression) {
		List<Graph> graphs = new ArrayList<>();
		expression.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>(true) {
			@Override
			public void meet(Graph graph) {
				graphs.add(graph);
				super.meet(graph);
			}
		});
		return graphs;
	}
